async () => {
 const query = '{{query|js}}'.trim().replace(/^https?:\/\/(?:dx\.)?doi\.org\//i, '');
 let data;
 if (/^10\.\d{4,9}\/\S+$/i.test(query)) {
  const response = await fetch('/works/' + encodeURIComponent(query), {credentials: 'omit', signal: AbortSignal.timeout(20000)});
  if (!response.ok) throw new Error('Crossref DOI 查询返回 HTTP ' + response.status);
  const record = await response.json();
  if (record.status !== 'ok' || record.message?.DOI?.toLowerCase() !== query.toLowerCase()) throw new Error('Crossref DOI 响应与查询不一致');
  data = {status: 'ok', message: {'total-results': 1, items: [record.message]}};
 } else data = JSON.parse(document.body.innerText);
 if (data.status !== 'ok' || !Array.isArray(data.message?.items)) throw new Error('Crossref 未返回有效出版物，检查当前页面');
 return {total: data.message['total-results'], works: data.message.items.map(w => ({doi: w.DOI, title: w.title?.[0] || '', authors: (w.author || []).map(a => [a.given,a.family].filter(Boolean).join(' ') || a.name || ''), publisher: w.publisher, journal: w['container-title']?.[0] || '', published: w.published?.['date-parts']?.[0], type: w.type, url: w.URL}))};
}
